using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text;
internal static partial class NativeBackground {
 static DateTime inkIdentityAt;static long inkIdentityImage,inkIdentityRoot;static string inkIdentity;
 static string VisibleInkIdentity(IntPtr h,long image,long root){if(inkIdentity!=null&&image==inkIdentityImage&&root==inkIdentityRoot&&DateTime.UtcNow-inkIdentityAt<TimeSpan.FromMilliseconds(1500))return inkIdentity;var queue=new Queue<long>();var seen=new HashSet<long>();ulong hash=14695981039346656037;int count=0;queue.Enqueue(root);while(queue.Count>0&&seen.Count<6000){long obj=queue.Dequeue();if(!seen.Add(obj))continue;foreach(long child in WidgetChildren(h,obj))queue.Enqueue(child);try{if(Pointer(h,obj)!=image+0x93ab1e8)continue;long data=Pointer(h,obj+0x28);if((BitConverter.ToUInt32(Read(h,data+8,4),0)&32768)==0)continue;hash=unchecked((hash^(ulong)obj)*1099511628211);count++;}catch{}}inkIdentityImage=image;inkIdentityRoot=root;inkIdentityAt=DateTime.UtcNow;return inkIdentity=count+":"+hash.ToString("x");}
 public static string InkText {get{return ReadInk("text");}set{SaveInk("text",value);}}
 public static string InkChat {get{return ReadInk("chat");}set{SaveInk("chat",value);}}
 public static string InkIcons {get{return ReadInk("icons");}set{SaveInk("icons",value);}}
 static string ReadInk(string key){string p=AppearanceProfiles.Path("ink-"+key+".txt");string s=File.Exists(p)?File.ReadAllText(p).Trim():"original";return Palette.IsColor(s)||(key=="canvas"&&s=="auto")?s:"original";}
 static void SaveInk(string key,string value){if(value!="original"&&!Palette.IsColor(value)&&!(key=="canvas"&&value=="auto"))throw new InvalidDataException("前景色应为 #RRGGBB 或 original。");Directory.CreateDirectory(Engine.Store);File.WriteAllText(AppearanceProfiles.Path("ink-"+key+".txt"),value);}
 public static void ResetInk(){InkText="original";InkIcons="original";InkChat="original";InkSecondary="original";InkCanvas="original";InkAccent="original";InkLink="original";IconEffects.Save(new IconSettings{Mode=0,Visibility=0,Outline=0});}
 sealed class InkTarget {public long Object,Table,Meta,PaintTable;public bool Chat;public int Index,Role;public uint Original,CanvasColor;}
 sealed class InkPlan {public long Root,ChatTable,CanvasWidget;public List<LinkTarget> Links=new List<LinkTarget>();public List<InkTarget> Apply=new List<InkTarget>(),Restore=new List<InkTarget>();}
 static InkPlan BuildInkPlan(IntPtr h,long image,long instance,long previous,bool removing){var p=new InkPlan{ChatTable=image+0x934fbd8,CanvasWidget=instance};if(previous!=0)try{if(Encoding.ASCII.GetString(Read(h,previous+0x30000,8))=="WXINK001"){int n=BitConverter.ToInt32(Read(h,previous+0x30008,4),0);if(n<0||n>256)throw new Exception("Ink records invalid");for(int i=0;i<n;i++){try{long at=previous+0x30010+i*48,obj=Pointer(h,at),table=Pointer(h,at+8),meta=Pointer(h,at+16);int index=BitConverter.ToInt32(Read(h,at+28,4),0);if(Pointer(h,obj)==table&&((meta==image+0x919a80&&index==5)||(meta==image+0x913530&&index==4)))p.Restore.Add(new InkTarget{Object=obj,Table=table,Meta=meta,Index=index,PaintTable=Pointer(h,at+40),Original=BitConverter.ToUInt32(Read(h,at+24,4),0)});}catch{}}}}catch{}
  if(InkIcons=="original"){var recovered=new Dictionary<long,InkTarget>();for(long distance=0x1000000;distance<0x70000000;distance+=0x1000000)foreach(long candidate in new[]{image+distance,image-distance})try{if(Encoding.ASCII.GetString(Read(h,candidate,7))!="WXBG001"||Encoding.ASCII.GetString(Read(h,candidate+0x30000,8))!="WXINK001")continue;int count=BitConverter.ToInt32(Read(h,candidate+0x30008,4),0);if(count<0||count>256)continue;for(int i=0;i<count;i++)try{long a=candidate+0x30010+i*48,obj=Pointer(h,a),table=Pointer(h,a+8),meta=Pointer(h,a+16);if(meta==image+0x913530&&!recovered.ContainsKey(obj)&&Pointer(h,obj)==table&&WidgetClass(h,image,obj)=="mmui::XImage")recovered.Add(obj,new InkTarget{Object=obj,Table=table,Meta=meta,Index=4,Original=BitConverter.ToUInt32(Read(h,a+24,4),0)});}catch{}}catch{}p.Restore.RemoveAll(t=>t.Index==4);p.Restore.AddRange(recovered.Values);}
  ReadPaintRegistry(h,image,previous,p);ReadLinkRegistry(h,image,previous,p);if(removing||(InkText=="original"&&InkChat=="original"&&InkLink=="original"))return p;long root=instance;for(int i=0;i<32;i++){long parent=Pointer(h,Pointer(h,root+8)+0x10);if(parent==0)break;root=parent;}if(WidgetClass(h,image,root)!="mmui::MainWindow")return p;p.Root=root;var q=new Queue<long>();var seen=new HashSet<long>();q.Enqueue(root);while(q.Count>0&&seen.Count<6000&&p.Apply.Count<256){long obj=q.Dequeue();if(!seen.Add(obj))continue;string cls=WidgetClass(h,image,obj);if(cls=="mmui::ChatTextItemView")p.ChatTable=Pointer(h,obj);if((obj==instance||cls=="mmui::MessageView")&&InkChat=="original")continue;foreach(var child in WidgetChildren(h,obj))q.Enqueue(child);if(cls!="mmui::XTextView")continue;bool icon=cls=="mmui::XImage";try{long d=Pointer(h,obj+0x28);if((BitConverter.ToUInt32(Read(h,d+8,4),0)&32768)==0)continue;bool excluded=false,isChat=false,inCanvas=false;long parent=Pointer(h,Pointer(h,obj+8)+0x10);if(icon&&WidgetClass(h,image,parent)!="mmui::XIcon")continue;for(int level=0;parent!=0&&parent!=root&&level<24;level++){string name=WidgetClass(h,image,parent);if(parent==instance||name=="mmui::MessageView")inCanvas=true;if(name=="mmui::ChatTextItemView"){isChat=true;p.ChatTable=Pointer(h,parent);}if(name.IndexOf("Avatar",StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf("Emoji",StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf("Emoticon",StringComparison.OrdinalIgnoreCase)>=0){excluded=true;break;}parent=Pointer(h,Pointer(h,parent+8)+0x10);}if(excluded||(isChat?InkChat:InkText)=="original")continue;uint original=BitConverter.ToUInt32(Read(h,obj+0x234,4),0);var known=p.Restore.FirstOrDefault(t=>t.Object==obj);if(known!=null)original=known.Original;int role=isChat?1:inCanvas?2:IsSecondaryInk(original)?3:0;p.Apply.Add(new InkTarget{Role=role,CanvasColor=role==2?CanvasColor(h,root,obj):0,PaintTable=0,Chat=isChat,Object=obj,Table=Pointer(h,obj),Meta=image+(icon?0x913530:0x919a80),Index=icon?4:5});}catch{}}
  return p;
 }
 static uint InkValue(string s){return Convert.ToUInt32(s.Substring(1),16)|0xff000000;}
 static void MetaCall(Code c,long obj,long meta,int call,int index,long argv){c.Rcx(obj);c.Emit(0xba);c.Emit(BitConverter.GetBytes(call));c.Emit(0x41,0xb8);c.Emit(BitConverter.GetBytes(index));c.Emit(0x49,0xb9);c.Imm(argv);c.AbsCall(meta);}
 static void WriteInkPlan(byte[] b,InkPlan p,long block,long image){Encoding.ASCII.GetBytes("WXINK001").CopyTo(b,0x30000);BitConverter.GetBytes(p.Apply.Count).CopyTo(b,0x30008);var c=new Code();c.Emit(0x48,0x83,0xec,0x38);RestoreLinkInk(c,p,image);foreach(var t in p.Restore){if(t.PaintTable!=0){c.Rax(t.PaintTable);c.Rdx(t.Object+0xc0);c.Emit(0x48,0x89,0x02);}long value=block+0x34030;c.Rax(value);c.Emit(0xc7,0x00);c.Emit(BitConverter.GetBytes(t.Original));c.Rax(value);c.Rdx(block+0x34038);c.Emit(0x48,0x89,0x02);MetaCall(c,t.Object,t.Meta,2,t.Index,block+0x34038);}
  if(InkText!="original")BitConverter.GetBytes(InkValue(InkText)).CopyTo(b,0x34000);if(InkIcons!="original")BitConverter.GetBytes(InkValue(InkIcons)).CopyTo(b,0x34004);if(InkChat!="original")BitConverter.GetBytes(InkValue(InkChat)).CopyTo(b,0x34008);BitConverter.GetBytes(block+0x34000).CopyTo(b,0x34010);BitConverter.GetBytes(block+0x34004).CopyTo(b,0x34018);BitConverter.GetBytes(block+0x34008).CopyTo(b,0x34020);
  for(int i=0;i<p.Apply.Count;i++){var t=p.Apply[i];int off=0x30010+i*48;long at=block+off;BitConverter.GetBytes((long)0).CopyTo(b,off+40);BitConverter.GetBytes(t.Object).CopyTo(b,off);BitConverter.GetBytes(t.Table).CopyTo(b,off+8);BitConverter.GetBytes(t.Meta).CopyTo(b,off+16);BitConverter.GetBytes(t.Index).CopyTo(b,off+28);BitConverter.GetBytes(at+24).CopyTo(b,off+32);MetaCall(c,t.Object,t.Meta,1,t.Index,at+32);MetaCall(c,t.Object,t.Meta,2,t.Index,t.Role==2?block+0xb0008+i*16:block+(t.Role==1?0x34020:t.Role==3?0x34070:0x34010));
}  c.Emit(0x48,0x83,0xc4,0x38,0xc3);var bytes=c.Finish();if(bytes.Length>0x10000)throw new IOException("前景色计划超限。");bytes.CopyTo(b,0x20000);WriteRoleData(b,p,block);WriteGlobalText(b,p,block,image);
 }
}




